import {getList, remove} from "@/api/treeManager/pzsx";
import PzsxAddEdit from "./components/pzsx/addedit.vue";
import store from "@/store";
//成本中心页面
export default {
  name: 'tabPzsx',
  components: {PzsxAddEdit},
  data() {
    return {
      tableloading: false,
      queryParams: {},
      page: {
        currentPage: 1,
        pageSize: 20,
        total: 0,
      },
      tableData: null,

      showAddEdit: false,
      fromValue: null,
      type: null,
    }
  },
  mounted() {
    this.page = {currentPage: 1, pageSize: 20, total: 0};
    this.getList();
  },
  methods: {
    getList() {
      this.tableloading = true;
      getList(this.page.currentPage, this.page.pageSize, this.queryParams).then(res => {
        const data = res.data;
        this.page.total = data.total;
        this.tableData = data.records;
        this.tableloading = false;
      });
    },
    pasxAddEditCallback() {
      this.getList();
      //刷新govern
      this.$store.dispatch("GetCustomId").then(() => {
      });
    },
    handelAdd() {
      this.type = 'add';
      this.showAddEdit = true;
    },
    handleEdit(row) {
      this.type = 'edit';
      this.showAddEdit = true;
      this.fromValue = row;
    },
    handelDelete(id) {
      if (id) {
        this.$confirm("确定将选择数据删除?", {
          confirmButtonText: "确定",
          cancelButtonText: "取消",
          type: "warning"
        }).then(() => {
          return remove(id);
        }).then(() => {
          this.getList();
          this.$message({
            type: "success",
            message: "删除成功!"
          });
        });
      } else {
        if (this.$refs.table.selection.length === 0) {
          this.$message.warning("请选择至少一条数据");
          return;
        }
        this.$confirm("确定将选择数据删除?", {
          confirmButtonText: "确定",
          cancelButtonText: "取消",
          type: "warning"
        }).then(() => {
          let ids = this.$refs.table.selection.map((item, index) => {
            return item.id
          }).join(',');
          return remove(ids);
        }).then(() => {
          this.getList();
          this.$message({
            type: "success",
            message: "操作成功!"
          });
        });
      }
    },
    Nindex(index) {
      return index + 1 + (this.page.currentPage - 1) * this.page.pageSize;
    },
    reset() {
      this.queryParams = {};
      this.page = {currentPage: 1, pageSize: 20, total: 0,};
      this.getList();
    },
    getTypeColor(type) {
      if (type == '0') {
        return '#209141';
      } else if (type == '1') {
        return '#4390F2';
      } else if (type == '2') {
        return '#000000';
      } else if (type == '3') {
        return '#000000';
      }
      return '#000000';
    },
    getTypeName(type) {
      if (type == '0') {
        return '属性';
      } else if (type == '1') {
        return '配置项';
      } else if (type == '2') {
        return '模型';
      } else if (type == '3') {
        return '字典模型';
      }
    },
  },
}
